parameters.query:
SELECT cm.odoo_lead_id, qr.framework, qr.assessment, qr.decision, qr.assessed_at, qr.assessed_by
FROM qualification_records qr
JOIN clients_master cm ON cm.id = qr.client_id
WHERE qr.id = {{ $json.qualification_record_id }}
LIMIT 1;

parameters.jsCode:
// 5.1.2.1 - Fields to Odoo lead custom-fields map
// PLACEHOLDER FIELD NAMES: this master plan flags (§10A.5 item 4) that no single Odoo
// data-dictionary doc exists yet for custom fields - these x_bant_/x_meddic_ names are
// PLACEHOLDERS and REQUIRE CONFIRMATION via fields_get introspection against the live
// Odoo instance before this goes to production. Do not treat as final.
const r = $input.item.json;
if (!r.odoo_lead_id) {
  return [{ json: { ...r, mapping_error: 'no odoo_lead_id found for this client - lead was never synced to Odoo (check Module 1.3)' } }];
}

const fields = {
  x_bant_budget: r.assessment && r.assessment.bant ? r.assessment.bant.budget : null,
  x_bant_authority: r.assessment && r.assessment.bant ? r.assessment.bant.authority : null,
  x_bant_need: r.assessment && r.assessment.bant ? r.assessment.bant.need : null,
  x_bant_timeline: r.assessment && r.assessment.bant ? r.assessment.bant.timeline : null,
  x_meddic_metrics: r.assessment && r.assessment.meddic ? r.assessment.meddic.metrics : null,
  x_meddic_economic_buyer: r.assessment && r.assessment.meddic ? r.assessment.meddic.economic_buyer : null,
  x_meddic_decision_criteria: r.assessment && r.assessment.meddic ? r.assessment.meddic.decision_criteria : null,
  x_meddic_decision_process: r.assessment && r.assessment.meddic ? r.assessment.meddic.decision_process : null,
  x_meddic_identify_pain: r.assessment && r.assessment.meddic ? r.assessment.meddic.identify_pain : null,
  x_meddic_champion: r.assessment && r.assessment.meddic ? r.assessment.meddic.champion : null,
  x_meddic_competition: r.assessment && r.assessment.meddic ? r.assessment.meddic.competition : null,
  x_qualification_decision: r.decision,
  x_qualification_assessed_at: r.assessed_at,
  x_qualification_assessed_by: r.assessed_by
};

return [{ json: { odoo_lead_id: r.odoo_lead_id, fields } }];

